8	-- Add social + ban columns (idempotent)
9	ALTER TABLE clients ADD COLUMN IF NOT EXISTS instagram_handle TEXT;
10	ALTER TABLE clients ADD COLUMN IF NOT EXISTS tiktok_handle     TEXT;
11	ALTER TABLE clients ADD COLUMN IF NOT EXISTS website_url       TEXT;
12	ALTER TABLE clients ADD COLUMN IF NOT EXISTS is_banned         BOOLEAN     NOT NULL DEFAULT false;
13	ALTER TABLE clients ADD COLUMN IF NOT EXISTS banned_reason     TEXT;
14	ALTER TABLE clients ADD COLUMN IF NOT EXISTS banned_at         TIMESTAMPTZ;
15	ALTER TABLE clients ADD COLUMN IF NOT EXISTS banned_by         UUID        REFERENCES auth.users(id) ON DELETE SET NULL;
16	
17	-- Handle format constraints (idempotent via DO block)
18	DO $$ BEGIN
19	  ALTER TABLE clients ADD CONSTRAINT clients_instagram_handle_fmt
20	    CHECK (instagram_handle IS NULL OR instagram_handle ~ '^[^@/]{1,100}$');
21	EXCEPTION WHEN duplicate_object THEN NULL; END $$;
22	DO $$ BEGIN
23	  ALTER TABLE clients ADD CONSTRAINT clients_tiktok_handle_fmt
24	    CHECK (tiktok_handle IS NULL OR tiktok_handle ~ '^[^@/]{1,100}$');
25	EXCEPTION WHEN duplicate_object THEN NULL; END $$;
26	
27	-- Website URL constraint (idempotent)
28	DO $$ BEGIN
29	  ALTER TABLE clients ADD CONSTRAINT clients_website_url_fmt
30	    CHECK (website_url IS NULL OR website_url ~ '^https?://.+');
31	EXCEPTION WHEN duplicate_object THEN NULL; END $$;
32	
33	-- Ban coherence constraints (idempotent)
34	DO $$ BEGIN
35	  ALTER TABLE clients ADD CONSTRAINT clients_ban_reason_required
36	    CHECK (NOT is_banned OR banned_reason IS NOT NULL);
37	EXCEPTION WHEN duplicate_object THEN NULL; END $$;
38	DO $$ BEGIN
39	  ALTER TABLE clients ADD CONSTRAINT clients_ban_at_required
40	    CHECK (NOT is_banned OR banned_at IS NOT NULL);
41	EXCEPTION WHEN duplicate_object THEN NULL; END $$;
42	
43	-- Partial index for fast "show all banned clients in studio" queries
44	CREATE INDEX IF NOT EXISTS idx_clients_banned ON clients (studio_id) WHERE is_banned = true;
45	
46	-- PII + ownership annotation
47	COMMENT ON COLUMN clients.is_banned IS 'S18 — Set via /api/clients/[id]/ban endpoint, owner/admin only at app layer';
48	COMMENT ON COLUMN clients.banned_reason IS 'PII:L2 — reason text visible to studio staff only';
49	COMMENT ON COLUMN clients.banned_by IS 'S18 — auth.users UUID of the staff member who issued the ban';
50	COMMENT ON COLUMN clients.instagram_handle IS 'S18 — handle only, no @ prefix (e.g. "janedoe" not "@janedoe")';
51	COMMENT ON COLUMN clients.tiktok_handle IS 'S18 — handle only, no @ prefix';
52	COMMENT ON COLUMN clients.website_url IS 'S18 — full URL including protocol (https://...)';
